/* ECLIPSE RPG — SPRITE ATLAS */
const ENEMY_ATLAS={sprites:[]};
const ENEMY_ATLAS_IMAGE=new Image();
ENEMY_ATLAS_IMAGE.onload=()=>{
  const sprites=[];
  for(let index=0;index<100;index++){
    const cell=document.createElement('canvas');
    cell.width=80;cell.height=80;
    const cellCtx=cell.getContext('2d',{willReadFrequently:true});
    cellCtx.imageSmoothingEnabled=false;
    cellCtx.drawImage(ENEMY_ATLAS_IMAGE,(index%10)*96+8,Math.floor(index/10)*96+8,80,80,0,0,80,80);
    const pixels=cellCtx.getImageData(0,0,80,80);
    const data=pixels.data;
    const key=[data[(79*80+79)*4],data[(79*80+79)*4+1],data[(79*80+79)*4+2]];
    let minX=80,minY=80,maxX=-1,maxY=-1;
    for(let offset=0;offset<data.length;offset+=4){
      if(Math.max(Math.abs(data[offset]-key[0]),Math.abs(data[offset+1]-key[1]),Math.abs(data[offset+2]-key[2]))<20)data[offset+3]=0;
      if(data[offset+3]){
        const pixel=offset/4,x=pixel%80,y=Math.floor(pixel/80);
        minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y);
      }
    }
    cellCtx.putImageData(pixels,0,0);
    sprites.push(maxX>=minX?{canvas:cell,x:minX,y:minY,width:maxX-minX+1,height:maxY-minY+1}:null);
  }
  ENEMY_ATLAS.sprites=sprites;
};
ENEMY_ATLAS_IMAGE.src='data:image/png;base64,';
ENEMY_ATLAS_IMAGE.onerror=()=>{console.error('Enemy atlas gagal dimuat dari data internal.');};

function getEnemyAtlasIndex(e,pat){
  const name=(e.n||'').toUpperCase();
  if(name.includes('KING')&&pat==='king')return 99;
  if(pat==='slime'){
    if(/RAJA|KING/.test(name))return 3;
    if(/ICE|BLUE|SEA|RIVER/.test(name))return /ICE/.test(name)?20:/SEA|RIVER/.test(name)?17:1;
    if(/LAVA|FIRE|RED/.test(name))return /LAVA/.test(name)?24:2;
    return 0;
  }
  if(pat==='humanoid'){
    if(/SKELETON ARCHER/.test(name))return 5;
    if(/SKELETON/.test(name))return 4;
    if(/ZOMBIE/.test(name))return 6;
    if(/GOBLIN/.test(name))return /ARCHER/.test(name)?13:12;
    if(/ORC/.test(name))return /WARLORD/.test(name)?15:14;
    if(/NINJA/.test(name))return 47;
    if(/SAMURAI/.test(name))return 48;
    if(/ARCHER|BANDIT/.test(name))return /ARCHER/.test(name)?58:57;
    if(/FISH|MERMAN/.test(name))return 18;
    return 4;
  }
  if(pat==='golem'||pat==='robot'){
    if(/ICE/.test(name))return 23;
    if(/LAVA/.test(name))return 27;
    if(/MECHA|TITAN/.test(name))return 73;
    return pat==='robot'?63:7;
  }
  if(pat==='bug'){
    if(/CRAB/.test(name))return 16;
    if(/SPIDER|SCORPION/.test(name))return /KING/.test(name)?53:44;
    if(/TURTLE/.test(name))return 37;
    return 44;
  }
  if(pat==='mushroom')return 50;
  if(pat==='bat')return 40;
  if(pat==='beast'){
    if(/WOLF/.test(name))return /ALPHA/.test(name)?56:9;
    if(/FISH|PIRANHA/.test(name))return 36;
    return 16;
  }
  if(pat==='imp')return /ALIEN/.test(name)?64:25;
  if(pat==='demon')return 97;
  if(pat==='winged'){
    if(/DEMON/.test(name))return /LORD/.test(name)?55:52;
    if(/HARPY/.test(name))return 77;
    if(/THUNDER|ZEUS/.test(name))return 71;
    return /ARCHER/.test(name)?29:28;
  }
  if(pat==='treant')return /ELDER|FOREST SPIRIT/.test(name)?35:10;
  if(pat==='ghost')return /SHADOW|WRAITH|BANSHEE/.test(name)?64:30;
  if(pat==='jellyfish')return 40;
  if(pat==='worm')return /SERPENT/.test(name)?26:42;
  if(pat==='dragon'){
    if(/KRAKEN/.test(name))return 19;
    if(/HYDRA/.test(name))return 37;
    if(/LEVIATHAN/.test(name))return 42;
    if(/FROST/.test(name))return 62;
    return 26;
  }
  if(pat==='king')return /ZEUS/.test(name)?95:59;
  return -1;
}

function drawEnemyAtlasSprite(e,pat){
  const index=getEnemyAtlasIndex(e,pat),sprite=ENEMY_ATLAS.sprites[index];
  if(!sprite)return false;
  const height=Math.max(e.boss?72:30,e.r*(e.boss?2.2:1.9));
  const width=height*sprite.width/sprite.height;
  ctx.save();
  ctx.imageSmoothingEnabled=false;
  ctx.drawImage(sprite.canvas,sprite.x,sprite.y,sprite.width,sprite.height,-width/2,-height/2,width,height);
  ctx.restore();
  return true;
}

